<?php
namespace App\Http\Controllers;
use App\Models\Alumno; use App\Models\User; use Illuminate\Http\Request;
class PadreHijoController extends Controller { public function index(){ return view('familias.index',['padres'=>User::where('role','padre')->orderBy('name')->get(),'alumnos'=>Alumno::where('activo',true)->orderBy('apellido')->get(),'vinculos'=>User::where('role','padre')->with('hijos')->get()]); } public function store(Request $request){ $datos=$request->validate(['padre_id'=>'required|exists:users,id','alumno_id'=>'required|exists:alumnos,id']); $padre=User::where('role','padre')->findOrFail($datos['padre_id']); $padre->hijos()->syncWithoutDetaching([$datos['alumno_id']]); return redirect()->route('admin.familias.index')->with('success','Vínculo familiar registrado correctamente.'); } public function destroy(User $padre, Alumno $alumno){ abort_unless($padre->role === 'padre',404); $padre->hijos()->detach($alumno->id); return redirect()->route('admin.familias.index')->with('success','Vínculo familiar eliminado.'); } }
